import{t as e}from"./chunks/ThreePanel.BddHBCcE.js";import{G as t,H as n,U as r,W as i,tt as a,z as o}from"./chunks/framework.DF4UzXOs.js";var s=JSON.parse(`{"title":"Shaders e Linguagens de Sombreamento","description":"O que são Shaders, linguagens (GLSL, HLSL, WGSL, MSL), pipelines programáveis e demonstrações interativas.","frontmatter":{"title":"Shaders e Linguagens de Sombreamento","sidebar_label":"Shaders","description":"O que são Shaders, linguagens (GLSL, HLSL, WGSL, MSL), pipelines programáveis e demonstrações interativas."},"headers":[],"relativePath":"shaders.md","filePath":"shaders.md","lastUpdated":0}`),c=Object.assign({name:`shaders.md`},{setup(s){return(s,c)=>(a(),n(`div`,null,[c[0]||=r(`<h1 id="shaders-e-programacao-grafica" tabindex="-1">Shaders e Programação Gráfica <a class="header-anchor" href="#shaders-e-programacao-grafica" aria-label="Permalink to “Shaders e Programação Gráfica”">​</a></h1><blockquote><p>Um <strong>Shader</strong> (sombreamento) é um pequeno programa escrito para ser executado diretamente nos milhares de núcleos paralelos da GPU. Eles controlam como cada vértice é transformado no espaço e qual cor cada pixel final recebe na tela.</p></blockquote><p>Antes dos anos 2000, as placas de vídeo possuíam pipelines de função fixa (<em>fixed-function pipeline</em>): o desenvolvedor só podia ligar ou desligar parâmetros pré-definidos. Hoje, todo o pipeline gráfico é programável através de shaders.</p><h2 id="demonstracoes-interativas" tabindex="-1">Demonstrações Interativas <a class="header-anchor" href="#demonstracoes-interativas" aria-label="Permalink to “Demonstrações Interativas”">​</a></h2><h3 id="_1-vertex-fragment-shader-em-tempo-real" tabindex="-1">1. Vertex &amp; Fragment Shader em Tempo Real <a class="header-anchor" href="#_1-vertex-fragment-shader-em-tempo-real" aria-label="Permalink to “1. Vertex &amp; Fragment Shader em Tempo Real”">​</a></h3><p>O painel abaixo demonstra um shader procedimental onde os vértices são deslocados por funções trigonométricas no tempo, enquanto o fragment shader gera um gradiente dinâmico com interpolação de cores.</p>`,6),t(e,{topic:`shaders`,title:`Shader Procedural Dinâmico`,subtitle:`Deformação senoidal de malha (Vertex Shader) e mapeamento cromático contínuo (Fragment Shader).`}),c[1]||=o(`h3`,{id:`_2-shaders-de-materiais-pbr-physically-based-rendering`,tabindex:`-1`},[i(`2. Shaders de Materiais PBR (Physically Based Rendering) `),o(`a`,{class:`header-anchor`,href:`#_2-shaders-de-materiais-pbr-physically-based-rendering`,"aria-label":`Permalink to “2. Shaders de Materiais PBR (Physically Based Rendering)”`},`​`)],-1),c[2]||=o(`p`,null,`Shaders modernos calculam interações da luz com propriedades físicas reais da matéria (como rugosidade e metalicidade).`,-1),t(e,{topic:`pbr`,title:`Matriz de Materiais PBR`,subtitle:`Variação de Roughness (eixo vertical) e Metalness (eixo horizontal) sob luz pontual em movimento.`}),c[3]||=r(`<hr><h2 id="tipos-de-shaders-no-pipeline-moderno" tabindex="-1">Tipos de Shaders no Pipeline Moderno <a class="header-anchor" href="#tipos-de-shaders-no-pipeline-moderno" aria-label="Permalink to “Tipos de Shaders no Pipeline Moderno”">​</a></h2><table tabindex="0"><thead><tr><th>Tipo de Shader</th><th>Estágio</th><th>O que processa</th><th>Exemplo de Aplicação</th></tr></thead><tbody><tr><td><strong>Vertex Shader</strong></td><td>Entrada de Geometria</td><td>Vértice individual</td><td>Transformação de coordenadas (matriz MVP), animação de esqueletos (skinning), ondas no mar</td></tr><tr><td><strong>Tessellation Shader</strong></td><td>Subdivisão</td><td>Primitivas poligonais</td><td>Adição dinâmica de detalhes geométricos conforme proximidade da câmera (LOD)</td></tr><tr><td><strong>Geometry Shader</strong></td><td>Pós-Vértices</td><td>Primitivas inteiras (triângulos/linhas)</td><td>Geração de partículas, wireframe, silhuetas e prismas volumétricos</td></tr><tr><td><strong>Fragment / Pixel Shader</strong></td><td>Rasterização</td><td>Pixel / Fragmento individual</td><td>Cálculo de iluminação (Phong, PBR), texturização, reflexos, sombras e neblina</td></tr><tr><td><strong>Compute Shader</strong></td><td>Processamento Geral (GPGPU)</td><td>Dados arbitrários em buffers</td><td>Simulação de fluidos, física de partículas, inteligência artificial e culling</td></tr><tr><td><strong>Mesh Shader</strong></td><td>Pipeline de Próxima Geração</td><td>Meshlets (blocos de triângulos)</td><td>Substitui Vertex + Geometry Shaders com controle fino (adotado no DX12 Ultimate e Vulkan)</td></tr></tbody></table><hr><h2 id="as-grandes-linguagens-de-shader" tabindex="-1">As Grandes Linguagens de Shader <a class="header-anchor" href="#as-grandes-linguagens-de-shader" aria-label="Permalink to “As Grandes Linguagens de Shader”">​</a></h2><ul><li><strong>GLSL (OpenGL Shading Language):</strong> Linguagem base do OpenGL e WebGL. Sintaxe muito próxima de C.</li><li><strong>HLSL (High-Level Shading Language):</strong> Linguagem proprietária da Microsoft para DirectX (D3D11, D3D12) e Xbox.</li><li><strong>WGSL (WebGPU Shading Language):</strong> A linguagem padrão da W3C para WebGPU no navegador, segura e fortemente tipada.</li><li><strong>MSL (Metal Shading Language):</strong> Baseada em C++14, desenvolvida pela Apple para iOS, iPadOS e macOS.</li><li><strong>SPIR-V:</strong> Representação intermediária binária padronizada pela Khronos. Permite escrever shaders em GLSL ou HLSL e compilá-los para um formato único que o driver da GPU consome diretamente.</li></ul><hr><h2 id="links-rapidos" tabindex="-1">Links Rápidos <a class="header-anchor" href="#links-rapidos" aria-label="Permalink to “Links Rápidos”">​</a></h2><ul><li><a href="https://thebookofshaders.com/" target="_blank" rel="noreferrer">The Book of Shaders</a> — o guia visual definitivo para iniciantes</li><li><a href="https://www.shadertoy.com/" target="_blank" rel="noreferrer">Shadertoy</a> — comunidade global para escrever e compartilhar fragment shaders no browser</li><li><a href="https://registry.khronos.org/OpenGL/specs/gl/GLSLangSpec.4.60.pdf" target="_blank" rel="noreferrer">Khronos GLSL Reference</a> — especificação oficial do GLSL 4.6</li><li><a href="https://learn.microsoft.com/windows/win32/direct3dhlsl/dx-graphics-hlsl" target="_blank" rel="noreferrer">Microsoft HLSL Guide</a> — documentação do HLSL no DirectX</li><li><a href="https://www.w3.org/TR/WGSL/" target="_blank" rel="noreferrer">W3C WGSL Specification</a> — especificação oficial do WebGPU Shading Language</li></ul><hr><h2 id="🚀-mega-link-dump-shaders-glsl-hlsl-wgsl" tabindex="-1">🚀 MEGA LINK DUMP - Shaders &amp; GLSL/HLSL/WGSL <a class="header-anchor" href="#🚀-mega-link-dump-shaders-glsl-hlsl-wgsl" aria-label="Permalink to “🚀 MEGA LINK DUMP - Shaders &amp; GLSL/HLSL/WGSL”">​</a></h2><h3 id="🎨-playgrounds-online-e-editores" tabindex="-1">🎨 Playgrounds Online e Editores <a class="header-anchor" href="#🎨-playgrounds-online-e-editores" aria-label="Permalink to “🎨 Playgrounds Online e Editores”">​</a></h3><ul><li><a href="https://www.shadertoy.com/" target="_blank" rel="noreferrer">Shadertoy</a> — / <a href="https://www.shadertoy.com/browse" target="_blank" rel="noreferrer">Explorar Shaders</a> / <a href="https://www.shadertoy.com/new" target="_blank" rel="noreferrer">Novo Shader</a> / <a href="https://www.shadertoy.com/howto" target="_blank" rel="noreferrer">Documentação</a> / <a href="https://www.shadertoy.com/" target="_blank" rel="noreferrer">Fórum</a></li><li><a href="https://glslsandbox.com/" target="_blank" rel="noreferrer">GLSL Sandbox</a> — editor minimalista de fragment shaders — / <a href="https://glslsandbox.com/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/mrdoob/glsl-sandbox" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://www.vertexshaderart.com/" target="_blank" rel="noreferrer">VertexShaderArt</a> — criação musical e visual com vertex shaders — / <a href="https://www.vertexshaderart.com/" target="_blank" rel="noreferrer">Website</a> / <a href="https://www.vertexshaderart.com/art" target="_blank" rel="noreferrer">Galeria</a></li><li><a href="https://computetoy.org/" target="_blank" rel="noreferrer">ComputeToy</a> — playground para compute shaders WebGPU em tempo real — / <a href="https://computetoy.org/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/compute-toy/compute-toy" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://cohost.org/" target="_blank" rel="noreferrer">Kitsunec Studio WebGPU</a> — testador de WGSL interativo no navegador — / <a href="https://webgpu.github.io/webgpu-samples/" target="_blank" rel="noreferrer">WebGPU Samples</a></li></ul><h3 id="📖-livros-tutoriais-e-cursos" tabindex="-1">📖 Livros, Tutoriais e Cursos <a class="header-anchor" href="#📖-livros-tutoriais-e-cursos" aria-label="Permalink to “📖 Livros, Tutoriais e Cursos”">​</a></h3><ul><li><a href="https://thebookofshaders.com/" target="_blank" rel="noreferrer">The Book of Shaders</a> — / <a href="https://thebookofshaders.com/" target="_blank" rel="noreferrer">Livro Online</a> / <a href="https://github.com/patriciogonzalezvivo/thebookofshaders" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://thebookofshaders.com/glossary/" target="_blank" rel="noreferrer">Glossário GLSL</a> / <a href="https://github.com/Book-of-Shaders-Examples" target="_blank" rel="noreferrer">Exemplos</a></li><li><a href="https://iquilezles.org/articles/" target="_blank" rel="noreferrer">Inigo Quilez Articles</a> — matemática, SDF (Signed Distance Fields), ruído e iluminação — / <a href="https://iquilezles.org/articles/" target="_blank" rel="noreferrer">Artigos Técnicos</a> / <a href="https://iquilezles.org/articles/distfunctions/" target="_blank" rel="noreferrer">SDF 3D Functions</a> / <a href="https://www.youtube.com/c/InigoQuilez" target="_blank" rel="noreferrer">YouTube</a></li><li><a href="https://learnopengl.com/Getting-started/Shaders" target="_blank" rel="noreferrer">LearnOpenGL: Shaders</a> — / <a href="https://learnopengl.com/Getting-started/Shaders" target="_blank" rel="noreferrer">Tutorial Básico</a> / <a href="https://learnopengl.com/PBR/Theory" target="_blank" rel="noreferrer">PBR Shading</a> / <a href="https://learnopengl.com/Guest-Articles/2022/Compute-Shaders/Introduction" target="_blank" rel="noreferrer">Compute Shaders</a></li><li><a href="https://www.ronja-tutorials.com/" target="_blank" rel="noreferrer">Ronja&#39;s Shader Tutorials</a> — shaders de alta qualidade em HLSL/Unity — / <a href="https://www.ronja-tutorials.com/" target="_blank" rel="noreferrer">Website</a> / <a href="https://www.patreon.com/ronja_tutorials" target="_blank" rel="noreferrer">Patreon</a></li><li><a href="https://catlikecoding.com/" target="_blank" rel="noreferrer">Catlike Coding: Custom SRP &amp; Shaders</a> — / <a href="https://catlikecoding.com/unity/tutorials/" target="_blank" rel="noreferrer">Tutoriais Unity/HLSL</a> / <a href="https://catlikecoding.com/unity/tutorials/rendering/" target="_blank" rel="noreferrer">Rendering Pipeline</a></li><li><a href="https://shader-learn.com/" target="_blank" rel="noreferrer">Shader-Learn</a> — plataforma interativa guiada para aprendizado de GLSL — / <a href="https://shader-learn.com/" target="_blank" rel="noreferrer">Website</a></li></ul><h3 id="🛠️-ferramentas-compiladores-e-depuradores" tabindex="-1">🛠️ Ferramentas, Compiladores e Depuradores <a class="header-anchor" href="#🛠️-ferramentas-compiladores-e-depuradores" aria-label="Permalink to “🛠️ Ferramentas, Compiladores e Depuradores”">​</a></h3><ul><li><a href="https://github.com/KhronosGroup/glslang" target="_blank" rel="noreferrer">glslang</a> — validador e compilador oficial de GLSL/HLSL para SPIR-V — / <a href="https://github.com/KhronosGroup/glslang" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/KhronosGroup/SPIRV-Cross" target="_blank" rel="noreferrer">SPIRV-Cross</a> — tradutor de SPIR-V para GLSL, HLSL, MSL e C++ — / <a href="https://github.com/KhronosGroup/SPIRV-Cross" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/gfx-rs/wgpu/tree/master/naga" target="_blank" rel="noreferrer">Naga (Rust)</a> — tradutor universal de shaders (WGSL, SPV, MSL, HLSL, GLSL) — / <a href="https://github.com/gfx-rs/wgpu" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/google/shaderc" target="_blank" rel="noreferrer">Shaderc (Google)</a> — pacote com wrappers em torno de glslang e spirv-tools — / <a href="https://github.com/google/shaderc" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://renderdoc.org/" target="_blank" rel="noreferrer">RenderDoc</a> — depurador gráfico profissional de frames e shaders — / <a href="https://renderdoc.org/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/baldurk/renderdoc" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://spector.babylonjs.com/" target="_blank" rel="noreferrer">Spector.js</a> — extensão de navegador para inspecionar comandos WebGL e shaders — / <a href="https://github.com/BabylonJS/Spector.js" target="_blank" rel="noreferrer">GitHub</a></li></ul><h3 id="👥-comunidades-de-shaders" tabindex="-1">👥 Comunidades de Shaders <a class="header-anchor" href="#👥-comunidades-de-shaders" aria-label="Permalink to “👥 Comunidades de Shaders”">​</a></h3><ul><li><a href="https://www.reddit.com/r/shaders/" target="_blank" rel="noreferrer">Reddit r/shaders</a> — / <a href="https://www.reddit.com/r/shaders/" target="_blank" rel="noreferrer">Comunidade</a></li><li><a href="https://www.reddit.com/r/shadertoy/" target="_blank" rel="noreferrer">Reddit r/shadertoy</a> — / <a href="https://www.reddit.com/r/shadertoy/" target="_blank" rel="noreferrer">Comunidade</a></li><li><a href="https://discord.gg/graphicsprogramming" target="_blank" rel="noreferrer">Discord Graphics Programming</a> — o maior servidor de programação gráfica do Discord</li></ul>`,19)]))}});export{s as __pageData,c as default};